"""Exact inference over the set F of all minimum-fault explanations.

The instance is compiled once into linear integer arithmetic: every link load
is an integer linear form ``Z = coeffs . q`` scaled by the least common
denominator of the edge's rational contributions, so observations, capacities
and controller windows are all integer constraints.  Faulty domains are free
booleans ``f_d`` with the single implication ``not f_d -> every observation of
d is satisfied``; the explanation set F is exactly the projection of

    base  AND  (#blamed domains <= k)

onto the demand variables, where k is the minimum attainable fault count.
Every reported quantity (ranges, forced/possible domains, controller
verdicts, witnesses) is then obtained from that one solved formula.
"""

import z3
from fractions import Fraction

from instance import InvalidInstance  # noqa: F401  (re-exported for callers)


class Infeasible(Exception):
    """No feasible explanation exists for the incident."""


def _lin(terms, ctx):
    """Integer linear expression from a list of coefficient*variable terms."""
    if not terms:
        return z3.IntVal(0, ctx=ctx)
    if len(terms) == 1:
        return terms[0]
    return z3.Sum(terms)


def _rat(value):
    """Exact reduced 'numerator/denominator' string of a Fraction."""
    return '%d/%d' % (value.numerator, value.denominator)


class _Engine(object):
    """Holds the compiled formula and answers queries about F."""

    def __init__(self, inst):
        self.inst = inst
        self.S = len(inst.snapshots)
        self.C = len(inst.commodities)
        self.E = len(inst.edges)
        self.ctx = z3.Context()
        self.sol = z3.Solver(ctx=self.ctx)
        self.opt = z3.Optimize(ctx=self.ctx)
        self.k = None
        base = self._build()
        self.sol.add(base)
        self.opt.add(base)

    # ------------------------------------------------------------------ build

    def _build(self):
        inst = self.inst
        ctx = self.ctx
        S, C, E = self.S, self.C, self.E
        cons = []

        self.q = [[z3.Int('q!%d!%d' % (i, ci), ctx=ctx) for ci in range(C)]
                  for i in range(S)]
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            for ci in range(C):
                lo, hi = bounds[ci]
                cons.append(self.q[i][ci] >= lo)
                cons.append(self.q[i][ci] <= hi)

        # Link loads: integer form scaled per edge, plus capacity limits.
        self.link = []
        for i in range(S):
            row = []
            for ei in range(E):
                scale, coeffs = inst.edge_coeff[ei]
                terms = [coeffs[ci] * self.q[i][ci] for ci in range(C) if coeffs[ci]]
                expr = _lin(terms, ctx)
                row.append(expr)
                if terms:
                    cons.append(expr <= scale * inst.edges[ei].capacity)
            self.link.append(row)

        self.ingress = {}
        self.egress = {}
        for i in range(S):
            for node in inst.nodes:
                iidx = inst.ingress_indices[node]
                if iidx:
                    self.ingress[(i, node)] = _lin([self.q[i][ci] for ci in iidx], ctx)
                eidx = inst.egress_indices[node]
                if eidx:
                    self.egress[(i, node)] = _lin([self.q[i][ci] for ci in eidx], ctx)

        self.fault_domains = inst.observed_domains()
        self.f = {}
        for domain in self.fault_domains:
            self.f[domain] = z3.Bool('f!%d' % inst.domain_index[domain], ctx=ctx)

        self.domain_violated = {}
        self.domain_satisfied = {}
        per_domain = {}
        for i in range(S):
            snap = inst.snapshots[i]
            for obs in snap.observations:
                if obs.metric == 'demand':
                    expr = self.q[i][inst.commodity_index[obs.target]]
                    lo, hi = obs.lower, obs.upper
                elif obs.metric == 'link':
                    ei = inst.edge_index[obs.target]
                    scale = inst.edge_coeff[ei][0]
                    expr = self.link[i][ei]
                    lo, hi = scale * obs.lower, scale * obs.upper
                elif obs.metric == 'ingress':
                    expr = self.ingress.get((i, obs.target), z3.IntVal(0, ctx=ctx))
                    lo, hi = obs.lower, obs.upper
                else:
                    expr = self.egress.get((i, obs.target), z3.IntVal(0, ctx=ctx))
                    lo, hi = obs.lower, obs.upper
                satisfied = z3.And(expr >= lo, expr <= hi)
                violated = z3.Or(expr < lo, expr > hi)
                if obs.domain is None:
                    cons.append(satisfied)
                else:
                    cons.append(z3.Or(self.f[obs.domain], satisfied))
                    per_domain.setdefault(obs.domain, []).append((violated, satisfied))
        for domain, items in per_domain.items():
            viols = [item[0] for item in items]
            sats = [item[1] for item in items]
            self.domain_violated[domain] = viols[0] if len(viols) == 1 else z3.Or(viols)
            self.domain_satisfied[domain] = sats[0] if len(sats) == 1 else z3.And(sats)
        self.fvars = [self.f[d] for d in self.fault_domains]
        return cons

    def _budget(self, count):
        """At most `count` blamed domains."""
        if count >= len(self.fvars):
            return z3.BoolVal(True, ctx=self.ctx)
        if not self.fvars:
            return z3.BoolVal(True, ctx=self.ctx)
        return z3.PbLe([(f, 1) for f in self.fvars], count)

    # ---------------------------------------------------------------- queries

    def _model(self, extra=()):
        """Model of base+extra, or None when unsatisfiable."""
        sol = self.sol
        sol.push()
        if extra:
            sol.add(*extra)
        res = sol.check()
        model = sol.model() if res == z3.sat else None
        sol.pop()
        if res == z3.unknown:
            raise RuntimeError('z3 returned unknown')
        return model

    def _sat(self, extra=()):
        return self._model(extra) is not None

    def _opt(self, expr, maximize, extra=()):
        """(best value, model) of expr over base+extra, or (None, None)."""
        opt = self.opt
        opt.push()
        if extra:
            opt.add(*extra)
        handle = opt.maximize(expr) if maximize else opt.minimize(expr)
        res = opt.check()
        if res == z3.sat:
            model = opt.model()
            value = model.eval(expr, model_completion=True).as_long()
        else:
            model = None
            value = None
        opt.pop()
        if res == z3.unknown:
            raise RuntimeError('z3 returned unknown')
        return value, model

    # ------------------------------------------------------------- extraction

    def _extract(self, model):
        """(demands, rational loads, actual faulty domain set) of a model."""
        inst = self.inst
        demands = [[model.eval(var, model_completion=True).as_long() for var in row]
                   for row in self.q]
        loads = [inst.edge_loads(demands[i]) for i in range(self.S)]
        faulty = set()
        for i, snap in enumerate(inst.snapshots):
            for obs in snap.observations:
                if not (obs.lower <= inst.true_value(obs, demands[i], loads[i]) <= obs.upper):
                    faulty.add(obs.domain)
        return demands, loads, faulty

    def _witness(self, demands, loads, faulty):
        inst = self.inst
        return {
            'demands': [[v for v in row] for row in demands],
            'links': [[_rat(v) for v in loads[i]] for i in range(self.S)],
            'faults': sorted(faulty),
        }

    # ------------------------------------------------------------------- run

    def run(self):
        inst = self.inst
        S, C, E = self.S, self.C, self.E

        # Overall feasibility under the fault budget.
        if not self._sat([self._budget(inst.max_faults)]):
            raise Infeasible()
        # Minimum attainable number of faulty domains.
        lo, hi = 0, inst.max_faults
        while lo < hi:
            mid = (lo + hi) // 2
            if self._sat([self._budget(mid)]):
                hi = mid
            else:
                lo = mid + 1
        k = lo
        self.k = k
        budget = self._budget(k)
        self.sol.add(budget)
        self.opt.add(budget)

        # One optimal explanation.
        model = self._model()
        demands, loads, faulty = self._extract(model)
        witness = self._witness(demands, loads, faulty)

        # Demand ranges over F (box bounds are free valid bounds).
        dmin = [[None] * C for _ in range(S)]
        dmax = [[None] * C for _ in range(S)]
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            for ci in range(C):
                lo, hi = bounds[ci]
                cur = demands[i][ci]
                if cur == lo:
                    dmin[i][ci] = lo
                else:
                    dmin[i][ci] = self._opt(self.q[i][ci], False)[0]
                if cur == hi:
                    dmax[i][ci] = hi
                else:
                    dmax[i][ci] = self._opt(self.q[i][ci], True)[0]

        # Link load ranges over F, deduplicated by symmetric edges.
        lmin = [[None] * E for _ in range(S)]
        lmax = [[None] * E for _ in range(S)]
        link_obs = {}
        for i in range(S):
            for obs in inst.snapshots[i].observations:
                if obs.metric == 'link':
                    ei = inst.edge_index[obs.target]
                    scale = inst.edge_coeff[ei][0]
                    key = (obs.domain, scale * obs.lower, scale * obs.upper)
                    link_obs.setdefault((i, ei), []).append(key)
        for i in range(S):
            bounds = inst.snapshots[i].bounds
            los = [b[0] for b in bounds]
            his = [b[1] for b in bounds]
            cache = {}
            for ei in range(E):
                scale, coeffs = inst.edge_coeff[ei]
                if not any(coeffs):
                    lmin[i][ei] = lmax[i][ei] = 0
                    continue
                sig = (scale, tuple(coeffs), scale * inst.edges[ei].capacity,
                       tuple(sorted(link_obs.get((i, ei), ()))))
                if sig in cache:
                    lmin[i][ei], lmax[i][ei] = cache[sig]
                    continue
                zlb = 0
                zub = scale * inst.edges[ei].capacity
                for ci in range(C):
                    if coeffs[ci]:
                        zlb += coeffs[ci] * los[ci]
                        zub += coeffs[ci] * his[ci]
                if zlb > zub:
                    zlb = zub
                cur = 0
                for ci in range(C):
                    if coeffs[ci]:
                        cur += coeffs[ci] * demands[i][ci]
                if zlb == zub:
                    mn = mx = zlb
                else:
                    mn = zlb if cur == zlb else self._opt(self.link[i][ei], False)[0]
                    mx = zub if cur == zub else self._opt(self.link[i][ei], True)[0]
                lmin[i][ei] = mn
                lmax[i][ei] = mx
                cache[sig] = (mn, mx)

        # Forced / possible faulty domains.
        forced = []
        possible = []
        for domain in self.fault_domains:
            if self._sat([self.domain_violated[domain]]):
                possible.append(domain)
                if not self._sat([self.domain_satisfied[domain]]):
                    forced.append(domain)

        # Controller verdicts.
        verdicts = []
        for i in range(S):
            snap = inst.snapshots[i]
            agree = []
            disagree = []
            for ci in range(C):
                c = snap.controller[ci]
                t = snap.tolerance
                agree.append(self.q[i][ci] >= c - t)
                agree.append(self.q[i][ci] <= c + t)
                disagree.append(z3.Or(self.q[i][ci] < c - t,
                                      self.q[i][ci] > c + t))
            some_agree = self._sat(agree)
            some_disagree = self._sat([z3.Or(disagree)]) if C else False
            if some_agree:
                verdicts.append('consistent' if not some_disagree else 'undetermined')
            else:
                verdicts.append('inconsistent')

        unique = all(dmin[i][ci] == dmax[i][ci]
                     for i in range(S) for ci in range(C))

        alternative = None
        if not unique:
            for i in range(S):
                for ci in range(C):
                    if dmin[i][ci] == dmax[i][ci]:
                        continue
                    if demands[i][ci] != dmin[i][ci]:
                        target = dmin[i][ci]
                    else:
                        target = dmax[i][ci]
                    model = self._model([self.q[i][ci] == target])
                    if model is None:
                        raise RuntimeError('range endpoint not attained')
                    d2, l2, f2 = self._extract(model)
                    alternative = self._witness(d2, l2, f2)
                    break
                if alternative is not None:
                    break

        snapshots = []
        for i in range(S):
            scale_of = [inst.edge_coeff[ei][0] for ei in range(E)]
            snapshots.append({
                'id': inst.snapshots[i].id,
                'demands': [[dmin[i][ci], dmax[i][ci]] for ci in range(C)],
                'links': [[_rat(Fraction(lmin[i][ei], scale_of[ei])),
                           _rat(Fraction(lmax[i][ei], scale_of[ei]))] for ei in range(E)],
                'verdict': verdicts[i],
            })

        return {
            'status': 'unique' if unique else 'ambiguous',
            'min_faults': k,
            'faults': {'forced': sorted(forced), 'possible': sorted(possible)},
            'snapshots': snapshots,
            'witness': witness,
            'alternative': alternative,
        }


def analyze(inst):
    """Full analysis of a validated instance; returns the response body."""
    engine = _Engine(inst)
    try:
        return engine.run()
    finally:
        engine.ctx = None
        engine.sol = None
        engine.opt = None
