#!/usr/bin/env python3
"""Offline WAN telemetry incident analyzer (public contract 1.1.1).

Reads UTF-8 JSON Lines requests on stdin, writes exactly one JSON response
object per request line on stdout, in order.
"""

import json
import sys

from instance import InvalidInstance, is_name, parse_request
import infer


def _reject_constant(_name):
    raise ValueError('nonstandard JSON constant')


def _respond(inst):
    try:
        body = infer.analyze(inst)
    except infer.Infeasible:
        return {'id': inst.id, 'status': 'infeasible'}
    body['id'] = inst.id
    return body


def process_line(raw):
    """Response object for one input line (bytes without terminator)."""
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    try:
        value = json.loads(text, parse_constant=_reject_constant)
    except ValueError:
        return {'id': None, 'status': 'error', 'error': 'malformed_json'}
    echo = None
    if isinstance(value, dict):
        rid = value.get('id')
        if is_name(rid):
            echo = rid
    try:
        inst = parse_request(value)
    except InvalidInstance:
        return {'id': echo, 'status': 'error', 'error': 'invalid_instance'}
    return _respond(inst)


def read_lines(stream):
    """Input lines as bytes; a final line without newline still counts."""
    data = stream.buffer.read()
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines.pop()
    return lines


def main():
    out = []
    for raw in read_lines(sys.stdin):
        try:
            out.append(process_line(raw))
        except Exception as exc:  # pragma: no cover - defensive only
            sys.stderr.write('internal error: %r\n' % (exc,))
            out.append({'id': None, 'status': 'error', 'error': 'invalid_instance'})
        sys.stdout.write(json.dumps(out[-1], separators=(',', ':')) + '\n')
        sys.stdout.flush()
    return 0


if __name__ == '__main__':
    sys.exit(main())
